      "devdoc": {
        "kind": "dev",
        "methods": {
          "getConfig(bytes32)": {
            "params": {
              "integrationId": "Unique identifier of the integration."
            },
            "returns": {
              "_0": "       The facet address and selector wires for the integration."
            }
          },
          "getConfigs(bytes32[])": {
            "params": {
              "integrationIds": "Array of integration identifiers."
            },
            "returns": {
              "integrationsConfig_": "       Array of configs corresponding to the given identifiers."
            }
          },
          "getDispatch(bytes4)": {
            "params": {
              "callSelector": "The 4-byte external call selector."
            },
            "returns": {
              "dispatch": "    The facet address and delegate selector for the given call selector."
            }
          },
          "getDispatches(bytes4[])": {
            "params": {
              "callSelectors": "Array of 4-byte external call selectors."
            },
            "returns": {
              "dispatches": "   Array of dispatch entries corresponding to the given selectors."
            }
          },
          "getRoleAdmin(bytes32)": {
            "details": "Returns the admin role that controls `role`. See {grantRole} and {revokeRole}. To change a role's admin, use {_setRoleAdmin}."
          },
          "getRoleMember(bytes32,uint256)": {
            "details": "Returns one of the accounts that have `role`. `index` must be a value between 0 and {getRoleMemberCount}, non-inclusive. Role bearers are not sorted in any particular way, and their ordering may change at any point. WARNING: When using {getRoleMember} and {getRoleMemberCount}, make sure you perform all queries on the same block. See the following https://forum.openzeppelin.com/t/iterating-over-elements-on-enumerableset-in-openzeppelin-contracts/2296[forum post] for more information."
          },
          "getRoleMemberCount(bytes32)": {
            "details": "Returns the number of accounts that have `role`. Can be used together with {getRoleMember} to enumerate all bearers of a role."
          },
          "grantRole(bytes32,address)": {
            "details": "Grants `role` to `account`. If `account` had not been already granted `role`, emits a {RoleGranted} event. Requirements: - the caller must have ``role``'s admin role. May emit a {RoleGranted} event."
          },
          "hasRole(bytes32,address)": {
            "details": "Returns `true` if `account` has been granted `role`."
          },
          "removeIntegration(bytes32)": {
            "params": {
              "id": "Unique identifier of the integration to remove."
            }
          },
          "renounceRole(bytes32,address)": {
            "details": "Revokes `role` from the calling account. Roles are often managed via {grantRole} and {revokeRole}: this function's purpose is to provide a mechanism for accounts to lose their privileges if they are compromised (such as when a trusted device is misplaced). If the calling account had been revoked `role`, emits a {RoleRevoked} event. Requirements: - the caller must be `callerConfirmation`. May emit a {RoleRevoked} event."
          },
          "revokeRole(bytes32,address)": {
            "details": "Revokes `role` from `account`. If `account` had been granted `role`, emits a {RoleRevoked} event. Requirements: - the caller must have ``role``'s admin role. May emit a {RoleRevoked} event."
          },
          "setIntegration(bytes32,(address,(bytes4,bytes4)[]))": {
            "params": {
              "config": "Facet address and array of selector wires to register.",
              "id": "Unique identifier for the integration."
            }
          }
        },
        "version": 1
      },
      "userdoc": {
        "kind": "user",
        "methods": {
          "getConfig(bytes32)": {
            "notice": "Returns the config for a single integration."
          },
          "getConfigs(bytes32[])": {
            "notice": "Returns configs for multiple integrations in a single call."
          },
          "getDispatch(bytes4)": {
            "notice": "Returns the dispatch entry for a call selector."
          },
          "getDispatches(bytes4[])": {
            "notice": "Returns dispatch entries for multiple call selectors in a single call."
          },
          "integrations()": {
            "notice": "Returns all registered integrations with their configs."
          },
          "removeIntegration(bytes32)": {
            "notice": "Removes an integration and all of its selector dispatches."
          },
          "setIntegration(bytes32,(address,(bytes4,bytes4)[]))": {
            "notice": "Registers or updates an integration with its facet address and selector wires."
          }
        },
        "version": 1
      }
